using System;using System.IO;using System.Linq;using System.Diagnostics;using V15Voice;
public static class AiSpeechRealTests {
 static int count;static void Check(bool b,string n){if(!b)throw new Exception(n);count++;Console.WriteLine("PASS "+n);}
 public static void Main(string[] args){string root=args[0],folder=Path.Combine(Path.GetTempPath(),"V15 Qwen Adam real "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);var cues=Scripts.ParseSrt("1\n00:00:00,000 --> 00:00:03,300\nJohn was standing there for a very long time because the door had finally opened.\n\n2\n00:00:03,500 --> 00:00:06,800\nThis small detail changes the whole story.\n");string source=Path.Combine(folder,"adam.srt");File.WriteAllText(source,Scripts.ToSrt(cues));string hash=StateFiles.Hash(source);var s=new VoiceSettings{Key="K:11",Mode=0,Device="cpu",Breathing=2,Normalize=false,Slow=false};var p=AiRepairSession.Open(source,cues,folder,s,false,"real Kokoro Adam 11");Func<string,KokoroEngine> factory=role=>new KokoroEngine{Root=root,Speaker=11,VoiceName="Adam · Kokoro",DeviceMode="cpu",Threads=2,Archive=new SpeechArchive(folder)};var timer=Stopwatch.StartNew();AiTimeline.Run(p,new LocalAi(root,"cpu"),factory,()=>false,(i,m)=>Console.WriteLine(i+" "+m),false);Check(p.Rows.All(r=>r.Original.Valid&&r.Original.Natural>0),"Every original unit is measured with actual native Adam Kokoro");foreach(var r in p.Rows){Console.WriteLine("ROW "+r.Stage.Number+" ORIGINAL "+r.Original.Natural+" "+r.Original.Detail);foreach(var a in r.Attempts)Console.WriteLine("AI "+a.Number+" "+String.Join(" ",a.Cues.Select(c=>c.Text))+" :: "+a.Error+" :: "+(a.Measurement==null?"no measure":a.Measurement.Detail+" "+a.Measurement.Natural+"s"));}Check(p.Rows[0].Original.NeedsRepair&&p.Rows[0].Attempts.Count>0,"Long real narration triggers actual Qwen rewrite, not a word-count-only rule");Check(p.Rows[0].Best!=null,"Qwen candidate passes actual Adam speech timing within allowed speeds");Check(p.Rows[0].Accepted==0&&p.Effective()[0].Text==cues[0].Text,"Real proposal waits for approval");p.Rows[0].Accepted=p.Rows[0].Best.Number;p.Save();var words=p.Effective();var o=new RenderOptions{AiRepair=p,Locked=true,SlowShort=false,Breathing=BreathMode.None,ReportContext=new VoiceReportContext{SourcePath=source,SourceCues=words,VoiceKey="K:11"}};using(var engine=factory("A")){string wav=Renderer.Render(words,engine,o,OutputFiles.Beside(source),(i,m)=>{});Check(FinalAudio.PcmFrames(wav)==163200&&File.Exists(wav),"Final full SRT renders exactly 6.8 seconds using the accepted correction");Check(o.RunReport.Units.All(u=>u.Before.HasValue&&u.Voice=="Adam · Kokoro")&&File.ReadAllText(o.RunReport.PathName).Contains("Gốc #1"),"Ordinary final voice report includes actual per-cue measures and full rewrite history");}Check(StateFiles.Hash(source)==hash,"Real end-to-end workflow preserves original SRT bytes");Console.WriteLine("TOTAL REAL AI SPEECH "+count+" passed in "+timer.Elapsed.TotalSeconds.ToString("0.0")+"s. CPU/Linux; no semantic score or physical GPU claim. "+folder);}
}
